import sys
import xml.etree.ElementTree as ET
import base64
import os
import random
import string

def generate_token():
    random_bytes = os.urandom(32)
    base64_bytes = base64.urlsafe_b64encode(random_bytes)
    return base64_bytes.decode('utf-8')

def parse_and_transform(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()

    for user in root.findall('user'):
        token = None
        for child in user:
            if child.tag == 'token':
                token = child.text
                break
        if token is None:
            user.append(ET.Element('token'))
            user[-1].text = generate_token()

    tree.write(sys.stdout, encoding='utf-8', xml_declaration=True, newl='\n')

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(1)
    parse_and_transform(sys.argv[1])
